package com.medilink.store.repository;
import com.medilink.store.entity.*; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*;
public final class Repositories { private Repositories(){} public interface Users extends JpaRepository<UserAccount,UUID>{Optional<UserAccount> findByEmailIgnoreCase(String email); boolean existsByEmailIgnoreCase(String email);} public interface Profiles extends JpaRepository<StoreOwnerProfile,UUID>{Optional<StoreOwnerProfile> findByUserId(UUID userId);} public interface Stores extends JpaRepository<Store,UUID>{Optional<Store> findFirstByStoreOwnerProfileId(UUID profileId);} public interface Medicines extends JpaRepository<Medicine,UUID>{} public interface Inventories extends JpaRepository<StoreInventory,UUID>{List<StoreInventory> findByStoreId(UUID storeId);} public interface Orders extends JpaRepository<Order,UUID>{List<Order> findAllByOrderByCreatedAtDesc();} public interface Customers extends JpaRepository<CustomerProfile,UUID>{Optional<CustomerProfile> findByUserId(UUID userId);} public interface Assignments extends JpaRepository<StoreOrderAssignment,UUID>{Optional<StoreOrderAssignment> findByOrderId(UUID orderId); List<StoreOrderAssignment> findByStoreId(UUID storeId);} }
